SELECT t1.tag_id, t1.collect_time, t1.last_base_val, t1.last_usage, t1.finish_flag FROM ems_collect_point_status t1 JOIN (
    SELECT tag_id, MAX(collect_time) AS max_time FROM ems_collect_point_status WHERE last_base_val > 0
        AND collect_time < #{collectTime}
        AND tag_id IN

            #{code}

        GROUP BY tag_id
    ) t2 ON t1.tag_id = t2.tag_id AND t1.collect_time = t2.max_time
WHERE t1.last_base_val > 0
